def is_point_symmetric(grid):
    rows, cols = len(grid), len(grid[0])
    for r in range(rows):
        for c in range(cols):
            val = grid[r][c]
            expected = grid[rows-1-r][cols-1-c]
            if val != expected:
                return False, (r, c, val, expected)
    return True, None

